1	<!doctype html>
2	<html lang="en" data-resolution="landscape">
3	  <head>
4	    <meta charset="UTF-8" />
5	    <meta name="viewport" content="width=1920, height=1080" />
6	    <title>Neon Border Loop</title>
7	    <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
8	    <style>
9	      * {
10	        margin: 0;
11	        padding: 0;
12	        box-sizing: border-box;
13	      }
14	      html,
15	      body {
16	        margin: 0;
17	        width: 1920px;
18	        height: 1080px;
19	        overflow: hidden;
20	        background: transparent;
21	      }
22	
23	      #root {
24	        position: relative;
25	        width: 1920px;
26	        height: 1080px;
27	        background: transparent;
28	      }
29	
30	      /* Traced rounded-rect: 576x432 PIP + 16px outward margin, corner radius
31	         28 (PIP) + 16 (margin) = 44, centered on the 1920x1080 canvas so it
32	         drops straight onto a centered webcam PIP. Wrap is padded well past
33	         the stroke on all sides so the blur bloom never gets clipped by the
34	         SVG viewport (a clipped bloom reads as a hard edge, not a glow). */
35	      #nb-wrap {
36	        position: absolute;
37	        left: 546px;
38	        top: 198px;
39	        width: 828px;
40	        height: 684px;
41	      }
42	      #nb-svg {
43	        position: absolute;
44	        inset: 0;
45	        display: block;
46	      }
47	    </style>
48	  </head>
49	  <body>
50	    <div
51	      id="root"
52	      data-composition-id="main"
53	      data-start="0"
54	      data-duration="3.6"
55	      data-width="1920"
56	      data-height="1080"
57	      data-fps="60"
58	    >
59	      <div id="nb-clip" class="clip" data-start="0" data-duration="3.6" data-track-index="0">
60	        <div id="nb-wrap">
61	          <svg
62	            id="nb-svg"
63	            width="828"
64	            height="684"
65	            viewBox="0 0 828 684"
66	            fill="none"
67	            aria-hidden="true"
68	          >
69	            <defs>
70	              <g id="nb-base"></g>
71	              <g id="nb-seg-a"></g>
72	              <g id="nb-seg-b"></g>
73	              <!-- Excludes the PIP's own footprint (16px inside the traced
74	                   rail) from every glow/core layer below, so blur bleed can
75	                   never soften into the area the webcam video occupies —
76	                   the interior stays hard-zero alpha no matter how wide the
77	                   blur reaches. Glow keeps radiating outward unaffected. -->
78	              <clipPath id="nb-exclude-interior" clipPathUnits="userSpaceOnUse">
79	                <path id="nb-exclude-path" clip-rule="evenodd" d="" />
80	              </clipPath>
81	            </defs>
82	            <g id="nb-clipped" clip-path="url(#nb-exclude-interior)">
83	              <g transform="translate(110,110)">
84	                <g id="nb-base-layers"></g>
85	                <path id="nb-rail" d="" fill="none" />
86	                <g id="nb-comet-layers"></g>
87	                <circle id="nb-head-a" r="9" fill="#ffffff" />
88	                <circle id="nb-head-b" r="9" fill="#ffffff" />
89	              </g>
90	            </g>
91	          </svg>
92	        </div>
93	      </div>
94	    </div>
95	
96	    <script>
97	      (function () {
98	        window.__timelines = window.__timelines || {};
99	
100	        var SVG_NS = "http://www.w3.org/2000/svg";
101	        var W = 608; // traced rectangle width  (576 PIP + 2*16 margin)
102	        var H = 464; // traced rectangle height (432 PIP + 2*16 margin)
103	        var R = 44; // corner radius            (28 PIP + 16 margin)
104	        var DUR = 3.6; // seconds — one full revolution, exactly 216 frames @ 60fps
105	
106	        var BLUE = "#12d6ff";
107	        var MAGENTA = "#ff2ec4";
108	
109	        function towardWhite(hex, amount) {
110	          var v = parseInt(hex.slice(1), 16);
111	          var out = "#";
112	          for (var s = 16; s >= 0; s -= 8) {
113	            var c = (v >> s) & 255;
114	            var m = Math.round(c + (255 - c) * amount);
115	            out += (m < 16 ? "0" : "") + m.toString(16);
116	          }
117	          return out;
118	        }
119	        var blueHot = towardWhite(BLUE, 0.88);
120	        var blueCore = towardWhite(BLUE, 0.35);
121	        var magentaHot = towardWhite(MAGENTA, 0.88);
122	
123	        // ---- geometry: rounded rect, clockwise, starting where the top
124	        // edge leaves the top-left corner arc ---------------------------
125	        var arc = "A " + R + " " + R + " 0 0 1 ";
126	        var d = [
127	          "M " + R + " 0",
128	          "H " + (W - R),
129	          arc + W + " " + R,
130	          "V " + (H - R),
131	          arc + (W - R) + " " + H,
132	          "H " + R,
133	          arc + "0 " + (H - R),
134	          "V " + R,
135	          arc + R + " 0",
136	          "Z",
137	        ].join(" ");
138	
139	        var railEl = document.getElementById("nb-rail");
140	        railEl.setAttribute("d", d);
141	
142	        // ---- interior exclusion clip: outer bounding box minus the PIP's
143	        // own rounded-rect footprint (576x432, r=28), positioned at the same
144	        // 16px inset from the traced rail used everywhere else. Evenodd
145	        // fill-rule turns "outer minus inner" into a single clip region that
146	        // covers everything except the PIP box. -----------------------------
147	        var PIP_X = 110 + 16; // 126 — absolute SVG coords (BLOOM_PAD + margin)
148	        var PIP_Y = 110 + 16;
149	        var PIP_W = 576;
150	        var PIP_H = 432;
151	        var PIP_R = 28;
152	        function roundedRectPath(x, y, w, h, r) {
153	          var a = "A " + r + " " + r + " 0 0 1 ";
154	          return [
155	            "M " + (x + r) + " " + y,
156	            "H " + (x + w - r),
157	            a + (x + w) + " " + (y + r),
158	            "V " + (y + h - r),
159	            a + (x + w - r) + " " + (y + h),
160	            "H " + (x + r),
161	            a + x + " " + (y + h - r),
162	            "V " + (y + r),
163	            a + (x + r) + " " + y,
164	            "Z",
165	          ].join(" ");
166	        }
167	        var outerD = "M -2000 -2000 H 2828 V 2684 H -2000 Z";
168	        var innerD = roundedRectPath(PIP_X, PIP_Y, PIP_W, PIP_H, PIP_R);
169	        document.getElementById("nb-exclude-path").setAttribute("d", outerD + " " + innerD);
170	
171	        var P = railEl.getTotalLength();
172	
173	        // Purely linear position: head(t) = (t / DUR) * P, wrapped mod P.
174	        // Constant path-length speed, no easing, no accumulator — a pure
175	        // function of t, and since it advances by exactly one full lap over
176	        // [0, DUR], head(DUR) === head(0) with matching velocity too, so the
177	        // motion is continuous straight through the loop point (no snap).
178	        function headAt(t) {
179	          var x = (t / DUR) * P;
180	          return ((x % P) + P) % P;
181	        }
182	
183	        // ---- always-on neon tube: full-perimeter static glow, present at
184	        // every frame so the border reads as a lit tube, not just a comet on
185	        // a dark rail ------------------------------------------------------
186	        var BASE_LAYERS = [
187	          { blur: 26, spread: 1.0, opacity: 0.16, stroke: BLUE },
188	          { blur: 13, spread: 0.5, opacity: 0.28, stroke: BLUE },
189	          { blur: 6, spread: 0.2, opacity: 0.42, stroke: BLUE },
190	          { blur: 0, spread: 0, opacity: 0.88, stroke: blueCore },
191	        ];
192	        var CORE_THICKNESS = 4;
193	        var MAX_REACH = 34;
194	
195	        var baseGroup = document.getElementById("nb-base-layers");
196	        BASE_LAYERS.forEach(function (layer) {
197	          var p = document.createElementNS(SVG_NS, "path");
198	          p.setAttribute("d", d);
199	          p.setAttribute("fill", "none");
200	          p.setAttribute("stroke", layer.stroke);
201	          p.setAttribute(
202	            "stroke-width",
203	            String(Math.max(0.5, CORE_THICKNESS + 2 * layer.spread * MAX_REACH)),
204	          );
205	          p.setAttribute("stroke-linejoin", "round");
206	          p.setAttribute("opacity", String(layer.opacity));
207	          if (layer.blur > 0) p.style.filter = "blur(" + layer.blur + "px)";
208	          baseGroup.appendChild(p);
209	        });
210	
211	        // ---- traveling comets: two hot arcs chasing around the loop,
212	        // offset half a lap apart. One skews cyan/white, the other
213	        // magenta/white — reads as an intensity peak sweeping through the
214	        // blue base color rather than a flat rotating dot. -----------------
215	        function buildSegments(groupId, count, falloff) {
216	          var g = document.getElementById(groupId);
217	          var segs = [];
218	          for (var i = 0; i < count; i++) {
219	            var p = document.createElementNS(SVG_NS, "path");
220	            p.setAttribute("d", d);
221	            p.setAttribute("fill", "none");
222	            p.setAttribute("stroke-linecap", i === 0 ? "round" : "butt");
223	            p.setAttribute("opacity", String(Math.pow(1 - i / count, falloff)));
224	            g.appendChild(p);
225	            segs.push(p);
226	          }
227	          return segs;
228	        }
229	
230	        var GLOW_SEGS = 22;
231	        var CORE_SEGS = 28;
232	        var arcFrac = 0.16; // fraction of the perimeter the comet trail covers
233	        var glowLen = arcFrac * P;
234	        var coreLen = 0.32 * glowLen;
235	
236	        var comets = [
237	          {
238	            offset: 0,
239	            hot: blueHot,
240	            base: BLUE,
241	            glow: buildSegments("nb-seg-a", GLOW_SEGS, 2.6),
242	          },
243	          {
244	            offset: P / 2,
245	            hot: magentaHot,
246	            base: MAGENTA,
247	            glow: buildSegments("nb-seg-b", GLOW_SEGS, 2.6),
248	          },
249	        ];
250	
251	        var COMET_LAYERS = [
252	          { blur: 30, spread: 1, opacity: 0.22, key: "base" },
253	          { blur: 15, spread: 0.6, opacity: 0.36, key: "base" },
254	          { blur: 8, spread: 0.3, opacity: 0.55, key: "base" },
255	          { blur: 4, spread: 0.05, opacity: 0.9, key: "hot" },
256	          { blur: 0, spread: -0.012, opacity: 1, key: "white" },
257	        ];
258	
259	        var overGroup = document.getElementById("nb-comet-layers");
260	        comets.forEach(function (comet) {
261	          var layerEls = [];
262	          COMET_LAYERS.forEach(function (layer) {
263	            var u = document.createElementNS(SVG_NS, "use");
264	            var color = layer.key === "white" ? "#ffffff" : layer.key === "hot" ? comet.hot : comet.base;
265	            u.setAttribute("href", "#" + comet.glow[0].parentNode.id);
266	            u.setAttribute("stroke", color);
267	            u.setAttribute(
268	              "stroke-width",
269	              String(Math.max(0.5, CORE_THICKNESS + 2 * layer.spread * MAX_REACH)),
270	            );
271	            u.setAttribute("opacity", String(layer.opacity));
272	            if (layer.blur > 0) u.style.filter = "blur(" + layer.blur + "px)";
273	            overGroup.appendChild(u);
274	            layerEls.push(u);
275	          });
276	          comet.layerEls = layerEls;
277	        });
278	
279	        /** Lay a segment run out behind `head`. Every value derives from head. */
280	        function layout(segs, head, length) {
281	          var step = length / segs.length;
282	          for (var i = 0; i < segs.length; i++) {
283	            var start = head - (i + 1) * step;
284	            start = ((start % P) + P) % P;
285	            segs[i].setAttribute("stroke-dasharray", step + " " + (P - step));
286	            segs[i].setAttribute("stroke-dashoffset", String(-start));
287	          }
288	        }
289	
290	        var headA = document.getElementById("nb-head-a");
291	        var headB = document.getElementById("nb-head-b");
292	        headA.style.filter = "blur(3px)";
293	        headB.style.filter = "blur(3px)";
294	        headA.setAttribute("fill", blueHot);
295	        headB.setAttribute("fill", magentaHot);
296	        headA.setAttribute("opacity", "0.95");
297	        headB.setAttribute("opacity", "0.95");
298	        var headEls = [headA, headB];
299	
300	        // Real (x,y) position of each comet head, recomputed every frame from
301	        // t alone. This is the element the check gate's motion sweep keys
302	        // off (a moving bbox), and it doubles as the brightest point of each
303	        // comet — the "hot spot" the light appears to emit from.
304	        function render(t) {
305	          for (var i = 0; i < comets.length; i++) {
306	            var head = headAt(t + comets[i].offset);
307	            layout(comets[i].glow, head, glowLen);
308	            var pt = railEl.getPointAtLength(head);
309	            headEls[i].setAttribute("cx", String(pt.x));
310	            headEls[i].setAttribute("cy", String(pt.y));
311	          }
312	        }
313	
314	        // ---- timeline: single linear driver spanning the whole clip. Every
315	        // frame is recomputed purely from t — seeking to frame N gives the
316	        // same state as playing to frame N, and the loop point (t=DUR wraps
317	        // to t=0) has matching position AND velocity, so there is no visible
318	        // seam when this file is looped in an editor. --------------------
319	        var tl = gsap.timeline({ paused: true });
320	        var driver = { t: 0 };
321	        tl.to(
322	          driver,
323	          {
324	            t: DUR,
325	            duration: DUR,
326	            ease: "none",
327	            onUpdate: function () {
328	              render(driver.t);
329	            },
330	          },
331	          0,
332	        );
333	
334	        render(0);
335	
336	        window.__timelines["main"] = tl;
337	      })();
338	    </script>
339	  </body>
340	</html>
341

