const fs = require('fs');

const W = 1920, H = 1080;
const files = {
  't=0.00s (frame 0)': 'raw_0.rgba',
  't=1.00s (frame 60)': 'raw_60.rgba',
  't=2.00s (frame 120)': 'raw_120.rgba',
};

const points = {
  'top-left corner (5,5)': [5, 5],
  'top-right corner (1914,5)': [1914, 5],
  'bottom-left corner (5,1074)': [5, 1074],
  'bottom-right corner (1914,1074)': [1914, 1074],
  'center (960,540)': [960, 540],
  'quiet region (300,900)': [300, 900],
};

function px(buf, x, y) {
  const off = (y * W + x) * 4;
  return [buf[off], buf[off + 1], buf[off + 2], buf[off + 3]];
}

function alphaStats(buf) {
  let min = 255, max = 0, sum = 0;
  const n = W * H;
  for (let i = 0; i < n; i++) {
    const a = buf[i * 4 + 3];
    if (a < min) min = a;
    if (a > max) max = a;
    sum += a;
  }
  return { min, max, avg: (sum / n).toFixed(2) };
}

for (const [label, file] of Object.entries(files)) {
  const buf = fs.readFileSync(file);
  console.log('\n=== ' + label + ' (' + file + ') ===');
  const stats = alphaStats(buf);
  console.log('  full-frame alpha stats: min=' + stats.min + ' max=' + stats.max + ' avg=' + stats.avg);
  for (const [plabel, [x, y]] of Object.entries(points)) {
    const [r, g, b, a] = px(buf, x, y);
    console.log('  ' + plabel + ': RGBA(' + r + ',' + g + ',' + b + ',' + a + ')');
  }
}
